1	/*
2	 * Deterministic mid-read fault injector for the sealmark test-suite.
3	 *
4	 * Loaded through LD_PRELOAD (Linux), this interposes the libc read entry
5	 * points and turns reads of *one specific regular file* into failures after
6	 * an exact number of bytes have already been delivered:
7	 *
8	 *   SEALMARK_READFAIL_PATH   absolute path of the file whose reads fail
9	 *   SEALMARK_READFAIL_AFTER  number of bytes that may be delivered first;
10	 *                            every subsequent read() on that file returns -1
11	 *                            with errno = EIO
12	 *
13	 * The file is opened completely normally (open/openat are not interposed),
14	 * so it is a genuine "opened successfully, then read() failed part way
15	 * through" situation rather than an open-time or permission failure.
16	 *
17	 * The target is identified by (st_dev, st_ino), so every other fd the
18	 * process reads -- the dynamic loader, OpenSSL, config files, other test
19	 * files -- is passed through untouched. When SEALMARK_READFAIL_AFTER is not
20	 * set the interposed functions are pure pass-throughs, which lets the same
21	 * preloaded library back the control tests that exercise normal EOF.
22	 *
23	 * libstdc++'s filebuf reads with the fortified __read_chk() alias when
24	 * _FORTIFY_SOURCE is enabled and plain read() otherwise, so both are
25	 * interposed. The implementation makes no file writes.
26	 */
27	
28	#define _GNU_SOURCE
29	
30	#include <dlfcn.h>
31	#include <errno.h>
32	#include <fcntl.h>
33	#include <stdint.h>
34	#include <stdlib.h>
35	#include <string.h>
36	#include <sys/stat.h>
37	#include <sys/types.h>
38	#include <unistd.h>
39	
40	typedef ssize_t (*read_fn_t)(int fd, void *buf, size_t nbytes);
41	typedef ssize_t (*read_chk_fn_t)(int fd, void *buf, size_t nbytes,
42	                                 size_t buflen);
43	
44	struct target {
45	    int valid;
46	    dev_t dev;
47	    ino_t ino;
48	    long remaining;  /* bytes still deliverable; <0 = injector disabled */
49	    int failing;     /* once set, the next target read fails */
50	};
51	
52	/*
53	 * Resolved once, on the first interposed read. dlsym() is deferred to that
54	 * point too: calling it from a constructor would itself be legal, but lazy
55	 * resolution keeps process startup identical to an un-preloaded run.
56	 */
57	static struct target g_target = {0, 0, 0, -1, 0};
58	static read_fn_t g_real_read;
59	static read_chk_fn_t g_real_read_chk;
60	
61	static void initialize(void) {
62	    const char *after = getenv("SEALMARK_READFAIL_AFTER");
63	    if (after != NULL && after[0] != '\0') {
64	        g_target.remaining = strtol(after, NULL, 10);
65	    }
66	
67	    const char *path = getenv("SEALMARK_READFAIL_PATH");
68	    if (path != NULL && g_target.remaining >= 0) {
69	        struct stat st;
70	        if (stat(path, &st) == 0 && S_ISREG(st.st_mode)) {
71	            g_target.dev = st.st_dev;
72	            g_target.ino = st.st_ino;
73	            g_target.valid = 1;
74	        }
75	    }
76	
77	    g_real_read = (read_fn_t)dlsym(RTLD_NEXT, "read");
78	    g_real_read_chk = (read_chk_fn_t)dlsym(RTLD_NEXT, "__read_chk");
79	}
80	
81	static int fd_is_target(int fd) {
82	    if (!g_target.valid) {
83	        return 0;
84	    }
85	    struct stat st;
86	    return fstat(fd, &st) == 0 && S_ISREG(st.st_mode) &&
87	           st.st_dev == g_target.dev && st.st_ino == g_target.ino;
88	}
89	
90	static ssize_t filter_read(int fd, void *buf, size_t nbytes, read_fn_t real) {
91	    /*
92	     * Disabled, or a read on some unrelated fd: behave exactly like libc.
93	     * fstat is only paid on target fds while the injector is enabled.
94	     */
95	    if (g_target.remaining < 0 || !fd_is_target(fd)) {
96	        return real(fd, buf, nbytes);
97	    }
98	
99	    if (g_target.failing) {
100	        errno = EIO;
101	        return -1;
102	    }
103	
104	    /*
105	     * Deliver at most the bytes of the pre-failure budget in this call.
106	     * More bytes are available in the file, so a plain read() of the
107	     * clipped length returns exactly that many and failure begins on the
108	     * following call -- the caller has genuinely received partial data.
109	     */
110	    if ((long)nbytes > g_target.remaining) {
111	        nbytes = (size_t)g_target.remaining;
112	    }
113	
114	    ssize_t got = real(fd, buf, nbytes);
115	    if (got > 0) {
116	        g_target.remaining -= got;
117	        if (g_target.remaining == 0) {
118	            g_target.failing = 1;
119	        }
120	    }
121	    return got;
122	}
123	
124	ssize_t read(int fd, void *buf, size_t nbytes) {
125	    if (g_real_read == NULL) {
126	        initialize();
127	    }
128	    if (g_real_read == NULL) {
129	        /* dlsym itself failed; there is no safe way to call libc read. */
130	        errno = ENOSYS;
131	        return -1;
132	    }
