17	constexpr size_t kSha256Size = 32;
18	constexpr std::string_view kDigestPrefix = "sha256:";
19	constexpr size_t kDigestHexLen = 2 * kSha256Size;  // 64 lowercase hex chars
20	constexpr std::string_view kSpkiFingerprintPrefix = "spki-sha256:";
21	
22	constexpr std::string_view kPemBegin = "-----BEGIN PUBLIC KEY-----";
23	constexpr std::string_view kPemEnd = "-----END PUBLIC KEY-----";
24	
25	int printUsage() {
26	    std::cerr << "Usage: sealmark --version\n"
27	                 "       sealmark digest <file>\n"
28	                 "       sealmark verify-digest <file> <expected-digest>\n"
29	                 "       sealmark key-id <public-key-file>\n";
30	    return 2;
31	}
32	
33	// ASCII whitespace permitted around the PEM block: the standard C/POSIX set
34	// of horizontal tab, LF, vertical tab, form feed, CR and space (the bytes for
35	// which Python's bytes.isspace() is true within ASCII). Everything else --
36	// including non-ASCII bytes -- is significant content and causes rejection.
37	bool isAsciiSpace(unsigned char c) {
38	    return c == ' ' || (c >= '\t' && c <= '\r');
39	}
40	
41	// --- Shared regular-file reading ------------------------------------------
42	//
43	// digest, verify-digest and key-id all walk the same pipeline: open the
44	// input, require the object actually opened to be a regular file, then read
45	// its complete raw bytes from the start in fixed-size passes until normal
46	// EOF, treating text and binary content identically. The three only differ
47	// in what happens to each chunk, which is expressed by a ByteSink (see
48	// processFileChunks):
49	//   * digest / verify-digest stream the bytes straight into SHA-256, so their
50	//     memory use does not grow with the file;
51	//   * key-id runs a streaming PEM parser over the chunks: the surrounding
52	//     ASCII whitespace and the base64 text are consumed byte by byte without
53	//     being retained, and only the decoded SubjectPublicKeyInfo DER is kept,
54	//     so its memory use tracks the (small) public-key encoding rather than
55	//     the file size.
56	// The error reporting for the open, file-type and read stages lives here
57	// once; sinks report only their own processing failures.
58	
59	// Size of every read pass for all three commands.
60	constexpr size_t kReadChunkSize = 64 * 1024;
61	
62	// Opens pathArg and requires the object actually opened -- the final target
63	// of any symlink chain, examined on the open file descriptor itself -- to be
64	// a regular file. The descriptor is fstat()ed, not the path: opening and the
65	// type decision are one and the same object, so there is no window in which a
66	// path that named a regular file at check time could be swapped for a FIFO or
67	// other non-regular object before it is opened. A FIFO is opened with
68	// O_NONBLOCK so the open itself never blocks waiting for the other end; the
69	// descriptor is closed immediately after fstat() shows it is not regular, so
70	// a FIFO's data is never read and no FIFO read can ever block. Once a regular
71	// file is held open, later reads always refer to that same file even if the
72	// path is renamed or replaced afterwards.
73	//
74	// The two pre-read failure stages stay distinct: a failure to open the path
75	// ("cannot open", covering a path that vanished, a dangling symlink or a
76	// traversal/permission error) and an object that opened but is not a regular
77	// file ("is not a regular file"). On failure prints a reason containing
78	// pathArg to stderr, closes any descriptor it opened and returns -1.
79	int openRegularInput(const char* pathArg) {
80	    // O_NONBLOCK keeps an open() on a FIFO without a writer from blocking;
81	    // it has no effect on regular files. O_CLOEXEC does not change behavior
82	    // for this process but keeps the descriptor from leaking if a later
83	    // change ever execs.
84	    int fd = ::open(pathArg, O_RDONLY | O_NONBLOCK | O_CLOEXEC);
85	    if (fd < 0) {
86	        const int err = errno;
87	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
88	                  << std::strerror(err) << '\n';
89	        return -1;
90	    }
91	
92	    struct stat st {};
93	    if (::fstat(fd, &st) != 0) {
94	        const int err = errno;
95	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
96	                  << std::strerror(err) << '\n';
97	        ::close(fd);
98	        return -1;
99	    }
100	    if (!S_ISREG(st.st_mode)) {
101	        std::cerr << "sealmark: '" << pathArg
102	                  << "' is not a regular file\n";
103	        ::close(fd);
104	        return -1;
105	    }
106	    return fd;
107	}
108	
109	// Closes the descriptor on destruction, so every failure path below -- a
110	// failed start(), a rejected chunk or a read error -- releases it.
111	class FdGuard {
112	public:
113	    explicit FdGuard(int fd) : fd_(fd) {}
114	    ~FdGuard() {
115	        if (fd_ >= 0) {
116	            ::close(fd_);
117	        }
118	    }
119	    FdGuard(const FdGuard&) = delete;
120	    FdGuard& operator=(const FdGuard&) = delete;
121	
122	private:
123	    int fd_;
124	};
125	
126	// Feeds a regular file's complete raw bytes to sink:
127	//   start()             once, immediately after the file is opened;
128	//   consume(data, size) for every non-empty chunk, including a final short
129	//                       one (a zero-length file yields no consume() call);
130	//   finish()            exactly once, only after a read reaching normal EOF.
131	// A false return aborts the operation and the sink is responsible for its own
132	// diagnostic. read() on a regular file is allowed to return fewer bytes than
133	// requested without meaning EOF (an interrupt, a short kernel read, ...), so
134	// each pass keeps reading until the buffer fills or read() reports zero; only
135	// a zero return is normal EOF. A read error -- including one after some bytes
136	// were already delivered -- is reported as such and never reaches finish(), so
137	// a mid-read failure can never surface as a digest, a match/mismatch result
138	// or a key fingerprint.
139	template <typename ByteSink>
140	bool processFileChunks(const char* pathArg, ByteSink& sink) {
141	    const int openedFd = openRegularInput(pathArg);
142	    if (openedFd < 0) {
143	        return false;
144	    }
145	    FdGuard fdGuard(openedFd);
146	    if (!sink.start()) {
147	        return false;
148	    }
149	
150	    std::vector<char> buffer(kReadChunkSize);
151	    while (true) {
152	        size_t filled = 0;
153	        bool reachedEof = false;
154	        while (filled < buffer.size()) {
155	            ssize_t got = 0;
156	            do {
157	                got = ::read(openedFd, buffer.data() + filled,
158	                             buffer.size() - filled);
159	            } while (got < 0 && errno == EINTR);
160	            if (got < 0) {
161	                // The file was already opened successfully; this is a
162	                // read-stage failure, never an open error or a content/format
163	                // problem -- even if earlier bytes of this pass were already
164	                // delivered to the sink.
165	                std::cerr << "sealmark: failed to read '" << pathArg
166	                          << "'\n";
167	                return false;
168	            }
169	            if (got == 0) {
170	                reachedEof = true;  // normal end of file
171	                break;
172	            }
173	            const size_t n = static_cast<size_t>(got);
174	            if (!sink.consume(buffer.data() + filled, n)) {
175	                return false;
176	            }
177	            filled += n;
178	        }
179	        if (reachedEof) {
180	            break;
181	        }
182	    }
183	
184	    return sink.finish();
185	}
186	
187	// Streams every chunk through SHA-256 with fixed-size buffers, so memory use
188	// stays constant regardless of file size. On a processing failure it prints
189	// the reason (including pathArg) itself; after success hash() holds exactly
190	// kSha256Size bytes.
191	class Sha256StreamSink {
192	public:
193	    explicit Sha256StreamSink(const char* pathArg) : pathArg_(pathArg) {}
194	
195	    bool start() {
196	        ctx_.reset(EVP_MD_CTX_new());
197	        if (!ctx_ ||
198	            EVP_DigestInit_ex(ctx_.get(), EVP_sha256(), nullptr) != 1) {
199	            fail("SHA-256 initialization failed");
200	            return false;
201	        }
202	        return true;
203	    }
204	
205	    bool consume(const char* data, size_t size) {
206	        if (EVP_DigestUpdate(ctx_.get(), data, size) != 1) {
207	            fail("SHA-256 computation failed");
208	            return false;
209	        }
210	        return true;
211	    }
212	
213	    bool finish() {
214	        unsigned int hashLen = 0;
215	        if (EVP_DigestFinal_ex(ctx_.get(), hash_, &hashLen) != 1 ||
216	            hashLen != kSha256Size) {
217	            fail("SHA-256 computation failed");
218	            return false;
219	        }
220	        return true;
221	    }
222	
223	    const unsigned char* hash() const { return hash_; }
224	
225	private:
226	    void fail(const char* what) {
227	        std::cerr << "sealmark: " << what << " for '" << pathArg_ << "'\n";
228	    }
229	
230	    const char* pathArg_;
231	    std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx_{
232	        nullptr, &EVP_MD_CTX_free};
233	    unsigned char hash_[kSha256Size] = {};
234	};
235	
236	// --- key-id input handling --------------------------------------------------
237	//
238	// The key-id input rules are split into three independent layers, each owning
239	// exactly one concern and testable in isolation:
240	//
241	//   1. StrictBase64Decoder -- the encoding rules for the payload characters:
242	//      alphabet, quantum assembly, padding placement and canonical unused
243	//      bits. It knows nothing about PEM markers, lines or whitespace.
244	//   2. PublicKeyPemParser -- the PEM text rules: surrounding whitespace, the
245	//      BEGIN/END markers and the line structure of the body. It decides which
246	//      characters are payload and hands them to the decoder; it never
247	//      inspects the base64 alphabet or assembles quanta itself.
248	//   3. isCanonicalSpkiDer -- the DER rules for the decoded payload: one
249	//      complete, canonical SubjectPublicKeyInfo covering every byte.
250	//
251	// PublicKeyPemSink then adapts the parser to the ByteSink interface used by
252	// processFileChunks and owns the key-id error reporting.
253	
254	// --- Layer 1: strict canonical Base64 decoding ------------------------------
255	//
256	// Incremental decoder for the payload of a PEM block. The rules enforced
257	// here, and only here:
258	//   * the alphabet is A-Z a-z 0-9 '+' '/'; every other character is invalid
259	//     ('-' is deliberately outside the alphabet, so a PEM boundary that
260	//     reaches the decoder fails here rather than being consumed);
261	//   * the stream is a whole number of 4-character quanta;
262	//   * '=' padding is legal only as the conventional "xx==" / "xxx=" tail of
263	//     the final quantum, no quantum may follow a padded one, and the unused
264	//     bits of the last data character must be zero -- non-canonical encodings
265	//     are rejected, never repaired;
266	//   * the decoded payload is at least one byte.
267	// Each quantum is decoded the moment its fourth character arrives, so no
268	// base64 text is ever accumulated; memory use tracks the decoded payload
269	// only.
270	class StrictBase64Decoder {
271	public:
272	    bool feed(unsigned char c) {
273	        quantum_[quantumLen_++] = c;
274	        if (quantumLen_ < 4) {
275	            return true;  // wait for the rest of the quantum
276	        }
277	        quantumLen_ = 0;
278	        return decodeQuantum();
279	    }
280	
281	    // At end of input the stream must have ended on a quantum boundary and
282	    // must decode to at least one byte.
283	    bool finish() const {
284	        return quantumLen_ == 0 && !decoded_.empty();
285	    }
286	
287	    // Valid only after finish() succeeded: the decoded payload bytes.
288	    const std::vector<unsigned char>& decoded() const { return decoded_; }
289	
290	private:
291	    static int valueOf(unsigned char c) {
292	        if (c >= 'A' && c <= 'Z') return c - 'A';
293	        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
294	        if (c >= '0' && c <= '9') return c - '0' + 52;
295	        if (c == '+') return 62;
296	        if (c == '/') return 63;
297	        return -1;
298	    }
299	
300	    // Decodes one assembled quantum, enforcing the padding and canonical-bit
301	    // rules. Decoding is strict and canonical, quantum by quantum.
302	    bool decodeQuantum() {
303	        const int a = valueOf(quantum_[0]);
304	        const int b = valueOf(quantum_[1]);
305	        if (a < 0 || b < 0) {
306	            return false;
307	        }
308	
309	        const bool pad2 = quantum_[2] == '=';
310	        const bool pad3 = quantum_[3] == '=';
311	        if (sawPadding_) {
312	            return false;  // no complete quantum may follow a padded one
313	        }
314	
315	        if (pad2) {
316	            if (!pad3) {
317	                return false;  // '=' at position 2 requires one at position 3
318	            }
319	            if ((b & 0x0f) != 0) {
320	                return false;  // non-canonical: unused padding bits must be 0
321	            }
322	            decoded_.push_back(
323	                static_cast<unsigned char>((a << 2) | (b >> 4)));
324	            sawPadding_ = true;
325	        } else {
326	            const int cv = valueOf(quantum_[2]);
327	            if (cv < 0) {
328	                return false;
329	            }
330	            if (pad3) {
331	                if ((cv & 0x03) != 0) {
332	                    return false;  // non-canonical: unused padding bits must be 0
333	                }
334	                decoded_.push_back(
335	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
336	                decoded_.push_back(static_cast<unsigned char>(
337	                    ((b & 0x0f) << 4) | (cv >> 2)));
338	                sawPadding_ = true;
339	            } else {
340	                const int d = valueOf(quantum_[3]);
341	                if (d < 0) {
342	                    return false;
343	                }
344	                decoded_.push_back(
345	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
346	                decoded_.push_back(static_cast<unsigned char>(
347	                    ((b & 0x0f) << 4) | (cv >> 2)));
348	                decoded_.push_back(static_cast<unsigned char>(
349	                    ((cv & 0x03) << 6) | d));
350	            }
351	        }
352	        return true;
353	    }
354	
355	    unsigned char quantum_[4] = {};
356	    size_t quantumLen_ = 0;
357	    bool sawPadding_ = false;  // a padded (final) quantum already occurred
358	    std::vector<unsigned char> decoded_;
359	};
360	
361	// --- Layer 2: PEM text structure --------------------------------------------
362	//
363	// Streaming parser for the strict single-block PEM structure used by key-id:
364	//
365	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
366	//   (payload lines; no blank or whitespace-only lines) ...
367	//   -----END PUBLIC KEY-----
368	//   [ASCII ws]
369	//
370	// The BEGIN line must end in LF or CRLF, but the END marker needs no line
371	// terminator at all: once it is fully matched, EOF may follow immediately or
372	// any number of ASCII whitespace bytes -- the conventional trailing LF or
373	// CRLF included, but also spaces or tabs glued directly to the marker, with
374	// no requirement that the first such byte be a line feed.
375	//
376	// Bytes are fed straight from the read passes, chunk by chunk, and nothing is
377	// retained besides the fixed-size parser state and the decoder's payload: the
378	// surrounding whitespace is merely classified and discarded, and every
379	// payload character is forwarded to the StrictBase64Decoder the moment it
380	// arrives. Memory use therefore depends on the size of the encoded public key
381	// itself, not on the amount of whitespace around the block or on the file
382	// size; no file-size limit is imposed.
383	//
384	// Anything outside the grammar above fails deterministically: non-whitespace
385	// outside the block, more than one block, any other PEM label (private keys,
386	// certificates, PKCS#1 RSA public keys, ...). Whether the payload characters
387	// themselves are well-formed base64 is the decoder's concern, not this
388	// parser's.
389	class PublicKeyPemParser {
390	public:
391	    bool feed(unsigned char c) {
392	        switch (phase_) {
393	            case Phase::kPreamble:
394	                if (isAsciiSpace(c)) {
395	                    return true;
396	                }
397	                if (c == static_cast<unsigned char>(kPemBegin[0])) {
398	                    markerMatched_ = 1;
399	                    phase_ = Phase::kBeginMarker;
400	                    return true;
401	                }
402	                return false;
403	
404	            case Phase::kBeginMarker:
405	                if (c == '\n') {
406	                    return markerMatched_ == kPemBegin.size() &&
407	                           beginComplete();
408	                }
409	                if (c == '\r') {
410	                    if (markerMatched_ != kPemBegin.size()) {
411	                        return false;
412	                    }
413	                    phase_ = Phase::kBeginCr;
414	                    return true;
415	                }
416	                if (markerMatched_ < kPemBegin.size() &&
417	                    c == static_cast<unsigned char>(kPemBegin[markerMatched_])) {
418	                    ++markerMatched_;
419	                    return true;
420	                }
421	                return false;
422	
423	            case Phase::kBeginCr:
424	                // A CR in the header is only legal as the CR of CRLF.
425	                return c == '\n' && beginComplete();
426	
427	            case Phase::kBodyLineStart:
428	                if (c == '-') {
429	                    markerMatched_ = 1;
430	                    phase_ = Phase::kEndMarker;
431	                    return true;
432	                }
433	                if (c == '\n') {
434	                    return false;  // no blank lines inside the block
435	                }
436	                if (isAsciiSpace(c)) {
437	                    return false;  // whitespace is allowed only around it
438	                }
439	                return feedPayloadChar(c);
440	
441	            case Phase::kBodyData:
442	                if (c == '\n') {
443	                    if (lineEmpty_) {
444	                        return false;  // blank or whitespace-only line
445	                    }
446	                    lineEmpty_ = true;
447	                    phase_ = Phase::kBodyLineStart;
448	                    return true;
449	                }
450	                if (c == '\r') {
451	                    if (lineEmpty_) {
452	                        return false;
453	                    }
454	                    phase_ = Phase::kBodyCr;
455	                    return true;
456	                }
457	                if (isAsciiSpace(c)) {
458	                    return false;
459	                }
460	                return feedPayloadChar(c);
461	
462	            case Phase::kBodyCr:
463	                // Bare CRs are not line separators: a CR must end with LF.
464	                if (c != '\n') {
465	                    return false;
466	                }
467	                lineEmpty_ = true;
468	                phase_ = Phase::kBodyLineStart;
469	                return true;
470	
471	            case Phase::kEndMarker:
472	                // While the marker is still incomplete its bytes must match
473	                // literally. A complete marker terminates the block outright:
474	                // LF/CRLF, spaces and tabs are all just postamble whitespace,
475	                // so the byte right after the final '-' need not be a line
476	                // feed. Whitespace inside a still-unfinished marker is not
477	                // part of the literal and fails like any other mismatch.
478	                if (markerMatched_ == kPemEnd.size()) {
479	                    if (isAsciiSpace(c)) {
480	                        return endComplete();
481	                    }
482	                    return false;
483	                }
484	                if (c == static_cast<unsigned char>(
485	                        kPemEnd[markerMatched_])) {
486	                    ++markerMatched_;
487	                    return true;
488	                }
489	                return false;
490	
491	            case Phase::kPostamble:
492	                // Everything still in the file must be ASCII whitespace; a
493	                // second block or any appended text is rejected, not ignored.
494	                return isAsciiSpace(c);
495	        }
496	        return false;
497	    }
498	
499	    // At end of input the text structure must be complete -- a fully matched
500	    // END marker, with or without trailing whitespace -- and the payload
501	    // stream must satisfy the decoder's own end-of-input rules.
502	    bool finish() const {
503	        bool structureComplete = false;
504	        switch (phase_) {
505	            case Phase::kEndMarker:
506	                // A fully matched END marker needs no trailing whitespace or
507	                // line feed at EOF; an unfinished match is a truncated marker.
508	                structureComplete = markerMatched_ == kPemEnd.size();
509	                break;
510	            case Phase::kPostamble:
511	                // Complete marker already followed by at least one whitespace
512	                // byte; everything remaining was whitespace as well.
513	                structureComplete = true;
514	                break;
515	            case Phase::kPreamble:       // empty or whitespace-only file
516	            case Phase::kBeginMarker:    // truncated BEGIN line
517	            case Phase::kBeginCr:        // CR in the header not followed by LF
518	            case Phase::kBodyLineStart:
519	            case Phase::kBodyData:
520	            case Phase::kBodyCr:         // truncated: no END line
521	                break;
522	        }
523	        return structureComplete && decoder_.finish();
524	    }
525	
526	    // Valid only after finish() succeeded: the decoded payload bytes.
527	    const std::vector<unsigned char>& payload() const {
528	        return decoder_.decoded();
529	    }
530	
531	private:
532	    enum class Phase {
533	        kPreamble,
534	        kBeginMarker,
535	        kBeginCr,
536	        kBodyLineStart,
537	        kBodyData,
538	        kBodyCr,
539	        kEndMarker,
540	        kPostamble,
541	    };
542	
543	    bool beginComplete() {
544	        phase_ = Phase::kBodyLineStart;
545	        lineEmpty_ = true;
546	        return true;
547	    }
548	
549	    bool endComplete() {
550	        phase_ = Phase::kPostamble;
551	        return true;
552	    }
553	
554	    // Hands one payload character to the decoder. The parser only records its
555	    // own line state; every encoding rule lives in the decoder.
556	    bool feedPayloadChar(unsigned char c) {
557	        phase_ = Phase::kBodyData;
558	        lineEmpty_ = false;
559	        return decoder_.feed(c);
560	    }
561	
562	    Phase phase_ = Phase::kPreamble;
563	    size_t markerMatched_ = 0;  // prefix length of the marker being matched
564	    bool lineEmpty_ = true;     // current body line has seen no data yet
565	    StrictBase64Decoder decoder_;
566	};
567	
568	// --- Layer 3: canonical SubjectPublicKeyInfo DER ----------------------------
569	//
570	// Validates that a decoded payload is one complete SubjectPublicKeyInfo DER
571	// structure covering every byte, understood by the crypto library, and in
572	// canonical encoding. Re-encoding the parsed structure must reproduce the
573	// payload byte for byte; that round trip rules out non-DER BER encodings and
574	// other representations OpenSSL might otherwise accept, without normalizing
575	// anything first. The bytes hashed for the fingerprint are therefore the
576	// canonical SPKI DER, so PEM line wrapping and line endings never influence
577	// the result.
578	bool isCanonicalSpkiDer(const std::vector<unsigned char>& der) {
579	    const unsigned char* p = der.data();
580	    const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
581	        d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(der.size()), nullptr,
582	                      nullptr),
583	        &EVP_PKEY_free);
584	    if (!pkey) {
585	        return false;
586	    }
587	    if (p - der.data() != static_cast<ptrdiff_t>(der.size())) {
588	        return false;  // trailing bytes after the SPKI structure
589	    }
590	
591	    const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
592	    if (encLen <= 0 || static_cast<size_t>(encLen) != der.size()) {
593	        return false;
594	    }
595	    std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
596	    unsigned char* q = reencoded.data();
597	    if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != der) {
598	        return false;  // non-canonical DER
599	    }
600	    return true;
601	}
602	
603	// ByteSink adapter for key-id: feeds the file bytes to the PEM parser chunk
604	// by chunk, applies the DER validation once the text and encoding layers have
605	// accepted the input, and reports every content failure in one place.
606	class PublicKeyPemSink {
607	public:
608	    explicit PublicKeyPemSink(const char* pathArg) : pathArg_(pathArg) {}
609	
610	    bool start() { return true; }
611	
612	    bool consume(const char* data, size_t size) {
613	        if (failed_) {
614	            return false;  // stay failed across the rest of the file
615	        }
616	        for (size_t i = 0; i < size; ++i) {
617	            if (!parser_.feed(static_cast<unsigned char>(data[i]))) {
618	                failed_ = true;
619	                reportInvalid();
620	                return false;
621	            }
622	        }
623	        return true;
624	    }
625	
626	    bool finish() {
627	        if (failed_) {
628	            return false;  // consume() already reported the reason
629	        }
630	        const bool ok =
631	            parser_.finish() && isCanonicalSpkiDer(parser_.payload());
632	        if (!ok) {
633	            failed_ = true;
634	            reportInvalid();
635	        }
636	        return ok;
637	    }
638	
639	    // Valid only after finish() succeeded: the canonical SPKI DER.
640	    const std::vector<unsigned char>& spkiDer() const {
641	        return parser_.payload();
642	    }
643	
644	private:
645	    void reportInvalid() const {
646	        std::cerr << "sealmark: '" << pathArg_
647	                  << "' does not contain a single valid PEM-encoded "
648	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
649	    }
650	
651	    PublicKeyPemParser parser_;
652	    bool failed_ = false;
653	    const char* pathArg_ = nullptr;
654	};
655	
656	// Renders bytes as lowercase hexadecimal with no separators or prefix.
657	std::string toHexLower(const unsigned char* data, size_t size) {
658	    static constexpr char kHex[] = "0123456789abcdef";
659	    std::string out;
660	    out.reserve(2 * size);
661	    for (size_t i = 0; i < size; ++i) {
662	        out.push_back(kHex[data[i] >> 4]);
663	        out.push_back(kHex[data[i] & 0x0f]);
664	    }
665	    return out;
666	}
667	
668	int digestFile(const char* pathArg) {
669	    Sha256StreamSink sink(pathArg);
670	    if (!processFileChunks(pathArg, sink)) {
671	        return 1;
672	    }
673	
674	    std::cout << kDigestPrefix
675	              << toHexLower(sink.hash(), kSha256Size) << '\n';
676	    return 0;
677	}
678	
679	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
680	// characters: no missing prefix, no uppercase, no other algorithm names,
681	// no surrounding whitespace or trailing content.
682	bool isValidExpectedDigest(std::string_view digest) {
683	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
684	        return false;
685	    }
686	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
687	        return false;
688	    }
689	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
690	        const char c = digest[i];
691	        const bool isHex =
692	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
693	        if (!isHex) {
694	            return false;
695	        }
696	    }
697	    return true;
698	}
699	
700	int verifyDigestFile(const char* pathArg, std::string_view expected) {
701	    Sha256StreamSink sink(pathArg);
702	    if (!processFileChunks(pathArg, sink)) {
703	        return 1;
704	    }
705	
706	    std::string actual;
707	    actual.reserve(kDigestPrefix.size() + kDigestHexLen);
708	    actual.append(kDigestPrefix);
709	    actual.append(toHexLower(sink.hash(), kSha256Size));
710	
711	    if (actual == expected) {
712	        std::cout << "match\n";
713	        return 0;
714	    }
715	    std::cout << "mismatch\n";
716	    return 3;
717	}
718	
719	int keyIdFile(const char* pathArg) {
720	    PublicKeyPemSink sink(pathArg);
721	    if (!processFileChunks(pathArg, sink)) {
722	        return 1;
723	    }
724	
725	    const std::vector<unsigned char>& spkiDer = sink.spkiDer();
726	    unsigned char hash[kSha256Size];
727	    unsigned int hashLen = 0;
728	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
729	                   EVP_sha256(), nullptr) != 1 ||
730	        hashLen != kSha256Size) {
731	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
732	                  << "'\n";
733	        return 1;
734	    }
735	
736	    std::cout << kSpkiFingerprintPrefix
737	              << toHexLower(hash, kSha256Size) << '\n';
738	    return 0;
739	}
740	
741	}  // namespace
742	
743	int main(int argc, char* argv[]) {
744	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
745	        std::cout << "sealmark 0.1.0\n";
746	        return 0;
747	    }
748	    if (argc == 3 && std::string_view(argv[1]) == "digest") {
749	        if (argv[2][0] == '\0') {
750	            return printUsage();
751	        }
752	        return digestFile(argv[2]);
753	    }
754	    if (argc == 3 && std::string_view(argv[1]) == "key-id") {
755	        if (argv[2][0] == '\0') {
756	            return printUsage();
757	        }
758	        return keyIdFile(argv[2]);
759	    }
760	    if (argc == 4 && std::string_view(argv[1]) == "verify-digest") {
761	        // Validate every argument before touching the file so that a bad
762	        // path and a malformed digest together still report a usage error.
763	        if (argv[2][0] == '\0' || !isValidExpectedDigest(argv[3])) {
764	            return printUsage();
765	        }
766	        return verifyDigestFile(argv[2], argv[3]);
767	    }
768	    return printUsage();
769	}
